# pip install langchain langchain-community rank-bm25

from langchain_community.retrievers import BM25Retriever
from langchain_core.documents import Document

# ─── DOCUMENTS ───
documents = [
    Document(
        page_content="Diabetes is a metabolic disease causing high blood sugar.",
        metadata={"category": "health", "id": 1}
    ),
    Document(
        page_content="Insulin is a hormone that regulates blood glucose levels.",
        metadata={"category": "health", "id": 2}
    ),
    Document(
        page_content="Exercise helps control blood sugar in diabetic patients.",
        metadata={"category": "health", "id": 3}
    ),
    Document(
        page_content="Quantum computing uses qubits for complex calculations.",
        metadata={"category": "tech", "id": 4}
    ),
    Document(
        page_content="Blockchain technology ensures secure and transparent transactions.",
        metadata={"category": "tech", "id": 5}
    ),
    Document(
        page_content="The Amazon rainforest produces 20 percent of Earth's oxygen.",
        metadata={"category": "environment", "id": 6}
    ),
]

# ─── BUILD BM25 RETRIEVER ───
bm25_retriever = BM25Retriever.from_documents(
    documents,
    k=3  # Return top 3
)

# ─── SEARCH FUNCTION WITH ANALYSIS ───
def bm25_retrieve_and_analyze(query: str):
    print(f"\n🔍 Query: '{query}'")
    print("-" * 55)
    results = bm25_retriever.invoke(query)
    print(f"📋 Retrieved {len(results)} documents:\n")
    for i, doc in enumerate(results, 1):
        print(f"  [{i}] Category: {doc.metadata['category']}")
        print(f"      Content: {doc.page_content}\n")

# ─── EXAMPLE SEARCHES ───
bm25_retrieve_and_analyze("blood sugar diabetes insulin")
bm25_retrieve_and_analyze("quantum blockchain technology")
bm25_retrieve_and_analyze("oxygen rainforest environment")
```

